// app/Sources/AgentServer+Grading.swift — the grading road map's op tools
// (spec §11 GR-6): `add_adjustment_clip`.

import Foundation

extension AgentServer {

    /// `add_adjustment_clip` — UI path: Insert ▸ Adjustment Clip. An
    /// omitted `duration` is the core's 5 s, as `add_text_clip`'s is; every
    /// refusal is the core's sentence.
    func addAdjustmentClip(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let track = try trackArg(a, "track", document)
        let at = try timeArg(a, "at", document)
        let duration = try optionalTimeArg(a, "duration", document)
        return try editResult(
            document, "Add Adjustment Clip",
            [.addAdjustmentClip(track: track.id, at: at, duration: duration)])
    }
}
/// resolves with no document open; `AppDelegate.validateMenuItem` enables it
/// while the bundled `GraphicsAPI.md` is there.
extension AppDelegate {

    /// "Insert", holding Adjustment Clip, then Graphic…, then Text Behind
    /// Subject.
    func insertMenu() -> NSMenu {
        let menu = NSMenu(title: "Insert")
        menu.addItem(
            item("Adjustment Clip", #selector(EditorViewController.insertAdjustmentClip(_:))))
        menu.addItem(item("Graphic…", #selector(EditorViewController.showGraphicBrowser(_:))))
        menu.addItem(
            item(
                "Text Behind Subject",
                #selector(EditorViewController.insertTextBehindSubject(_:))))
        return menu
    }

    /// File's graphic-file group (spec §11 G-30 (a)): a separator, then
    /// Rename Graphic…, Delete Graphic… and Restore Graphic Version…, each a
    /// nil-target selector the editor implements and validates
//! The qualifier's two rules for action evaluation (spec §11 GR-13, GR-35),
//! beside `actions.rs` rather than in it (that file is near the cap), as
//! GR-12's `actions_curves.rs` is.
//!
//! §5.4 interpolates numbers, so an animated hue centre from 350 to 10
//! would sweep the long way round, through the greens and blues at 180.
//! The owner chose the SHORT way round (G2-4's choice 11): before the lerp,
//! [`align_hue_center`] moves the interpolation TARGET's centre by ±360 when
//! the two centres are more than 180 degrees apart, so the lerp takes the
//! shorter arc (350 → 370), and `actions_clamp_grade.rs`'s `clamp_qualifier`
//! brings the lerped centre back onto the circle with `rem_euclid 360`
//! (355, then 0, then 5). Two centres exactly 180 apart have no shorter
//! arc and go linearly. Only the target of the action the time is INSIDE
//! is touched: an ended action's end is merged as written.
//!
//! [`qualifier_json`] writes a qualifier with its `blur` always present
//! (GR-35), where the file leaves a 0 out: §5.4's lerp walks only its FROM
//! side's keys, so a blur absent there would not animate from 0 and would
//! jump at the end. `actions.rs`'s `video_json` writes a non-neutral
//! qualifier through it; a neutral one stays absent, so a qualifier turned
//! on still switches at the end, as a range does.

use serde_json::Value;

use crate::actions::to_json;
use crate::model::Qualifier;

/// `qualifier` as JSON with `"blur"` always present, even at 0 (module doc).
pub(crate) fn qualifier_json(qualifier: &Qualifier) -> Value {
    let mut value = to_json(qualifier);
    if let Value::Object(fields) = &mut value {
        fields.insert("blur".to_string(), to_json(&qualifier.blur));
    }
    value
}

/// The `video.qualifier.hue.center` number of an action state, mutably.
fn center(state: &mut Value) -> Option<&mut Value> {
    state
        .get_mut("video")?
        .get_mut("qualifier")?
        .get_mut("hue")?
        .get_mut("center")
}

/// On the two states' `video.qualifier.hue.center`, when both are numbers
/// and more than 180 apart: `to`'s centre moves by ±360 so the two are less
/// than 180 apart (module doc). Anything else is left alone.
pub(crate) fn align_hue_center(from: &mut Value, to: &mut Value) {
    let Some(start) = center(from).and_then(|value| value.as_f64()) else {
        return;
    };
    let Some(end) = center(to) else {
        return;
    };
    let Some(target) = end.as_f64() else {
        return;
    };
    let turn = crate::model::HUE_TURN;
    let moved = if target - start > turn / 2.0 {
        target - turn
    } else if start - target > turn / 2.0 {
        target + turn
    } else {
        return;
    };
    if let Some(number) = serde_json::Number::from_f64(moved) {
        *end = Value::Number(number);
    }
}
