/// `Ok` when every present range is inside its bounds (all inclusive, spec
/// §11 GR-13): the hue's `center` and `width` 0…360 and its `softness`
/// 0…180; each level range's `low`, `high` and `softness` 0…1 and `low ≤
/// high`. The first refusal otherwise, in the order hue (centre, width,
/// softness), saturation (low, high, softness, then the order), luma the
/// same; then `blur` 0…1 (GR-35), last. A bound is compared exactly, so
/// 360, 180, 0 and 1 all pass.
pub(crate) fn check_qualifier(qualifier: &Qualifier) -> Result<(), String> {
    if let Some(hue) = &qualifier.hue {
        in_range("video.qualifier.hue.center", hue.center, 0.0, HUE_TURN)?;
        in_range("video.qualifier.hue.width", hue.width, 0.0, HUE_TURN)?;
        in_range(
            "video.qualifier.hue.softness",
            hue.softness,
            0.0,
            HUE_SOFTNESS_MAX,
        )?;
    }
    for (name, range) in qualifier.levels() {
        let Some(range) = range else {
            continue;
        };
        let key = format!("video.qualifier.{name}");
        in_range(&format!("{key}.low"), range.low, 0.0, 1.0)?;
        in_range(&format!("{key}.high"), range.high, 0.0, 1.0)?;
        in_range(&format!("{key}.softness"), range.softness, 0.0, 1.0)?;
        if range.low > range.high {
            return Err(format!(
                "{key}.low ({}) must not be greater than {key}.high ({})",
                range.low, range.high
            ));
        }
    }
    in_range(
        "video.qualifier.blur",
        qualifier.blur,
        0.0,
        QUALIFIER_BLUR_MAX,
    )
}
/// pixels an adjustment clip grades. A range that is `None` is off and
/// passes everything; the weight is the product of the present ranges, then
/// its complement when `invert` is set. `blur` (format 21, GR-35) softens
/// that weight by a Gaussian before the pass reads it.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Qualifier {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub hue: Option<HueRange>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub saturation: Option<LevelRange>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub luma: Option<LevelRange>,
    #[serde(skip_serializing_if = "is_false")]
    pub invert: bool,
    #[serde(skip_serializing_if = "is_zero")]
    pub blur: f64,
}

impl Qualifier {
    /// No range, not inverted and no blur (GR-35): `video.qualifier` is not
    /// written, and the adjustment pass weighs every pixel as it did before
    /// the key existed.
    pub fn is_neutral(&self) -> bool {
        self.hue.is_none()
            && self.saturation.is_none()
            && self.luma.is_none()
            && !self.invert
            && self.blur == 0.0
    }

    /// The two level ranges with their names, in model order.
    pub fn levels(&self) -> [(&'static str, &Option<LevelRange>); 2] {
        [("saturation", &self.saturation), ("luma", &self.luma)]
    }
}

/// Whether `invert` is off, and so left out of the file.
fn is_false(value: &bool) -> bool {
    !*value
